}

lessons.solution:
function leafPaths(obj) {
  const result = [];
  function visit(value, prefix) {
    if (value === null || typeof value !== "object") { result.push(prefix); return; }
    for (const [key, child] of Object.entries(value)) {
      visit(child, prefix === "" ? key : prefix + "." + key);
    }
  }
  visit(obj, "");
  return result;
}

